-- ==============================================================================
-- SEED DATA: Suggest Key Demo Records
-- Description: Contains all demo/seed data for the Suggest Key platform.
--              This data preserves the existing demo experience while moving
--              from frontend hardcoded data to Supabase database records.
--
-- IMPORTANT: All records have is_demo = true to identify them as seed data.
-- ==============================================================================

-- ==============================================================================
-- 1. PROFILES (Demo Users)
-- ==============================================================================
ON CONFLICT (id) DO NOTHING;

-- ==============================================================================
-- 2. CATEGORIES (Legacy support)
-- ==============================================================================
ON CONFLICT (id) DO NOTHING;

-- ==============================================================================
-- 3. ADVISORY SEGMENTS (if not already seeded)
-- ==============================================================================
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    short_description = EXCLUDED.short_description,
    updated_at = timezone('utc'::text, now());

-- ==============================================================================
-- 4. MENTORS (All 19 demo advisors)
-- ==============================================================================

-- Mental Health Advisors
ON CONFLICT (id) DO NOTHING;

-- Relationship Advisors
ON CONFLICT (id) DO NOTHING;

-- Career Advisors
