INSERT INTO public.categories (id, name, slug, description, icon_name, requires_credential_verification, display_order) VALUES
('relationship', 'Relationship', 'relationship', 'Partnership calibration, interpersonal dynamics, family systems & high-stakes conflict resolution.', 'Heart', true, 1),
