INSERT INTO public.advisory_segments (id, name, slug, short_description, tagline, description, icon, accent, badge, use_cases, audience, advisor_types, what_to_expect, responsible_note, is_active, display_order) VALUES
('00000000-0000-0000-0000-000000000001', 'Relationship Advisory', 'relationship', 'Structured guidance for interpersonal communication, conflict resolution, and healthy partnership dynamics.', 'Build healthier, clearer and more meaningful relationships with structured guidance from experienced relationship professionals.', 'Whether you are navigating communication challenges, recurring conflict, changing relationship dynamics or family concerns, the right advisor can help you understand the situation and work toward clearer next steps.', 'Heart', '#ffb829', 'LMFT & Certified Mediators', '["Struggling with recurring conflict patterns or communication breakdowns", "Navigating a key relationship transition or pre-commitment decision", "Setting healthy boundaries and seeking neutral, objective perspective"]'::jsonb, 'Individuals • Couples • Families', '["Licensed Marriage & Family Therapists (LMFT)", "Certified Gottman Method Practitioners", "Systemic Family & Interpersonal Mediators"]'::jsonb, '["45-minute confidential video consultation", "Objective analysis of relationship loops and communication triggers", "Practical conversation frameworks and boundary templates"]'::jsonb, NULL, true, 1),
('00000000-0000-0000-0000-000000000002', 'Career Advisory', 'career', 'High-leverage perspective on professional direction, promotion roadmap, executive leadership, and negotiations.', 'Make clearer decisions about your professional direction, growth, leadership, and next career move.', 'From choosing your next career move to navigating leadership, interviews or professional transitions, career advisors provide structured perspective to help you move forward with confidence.', 'Briefcase', '#8052ff', 'Executive Leaders & Directors', '["Deciding between career paths or evaluating high-stakes job offers", "Aiming for promotion, executive leadership, or team scaling", "Preparing for strategic interviews and negotiating compensation"]'::jsonb, 'Professionals • Leaders • Founders', '["VP & C-Suite Tech Operators (Ex-Meta, Uber, Stripe)", "Group Product Managers & Engineering Directors", "Certified Executive Coaches & Compensation Strategists"]'::jsonb, '["1:1 diagnostic on career trajectory and positioning", "Executive resume, dossier, and promotion narrative review", "Live mock interviews and executive stakeholder pitching practice"]'::jsonb, NULL, true, 2),
('00000000-0000-0000-0000-000000000003', 'Mental Health Advisory', 'mental-health', 'Confidential conversations for stress management, emotional regulation, cognitive resilience, and life transitions.', 'Find a trusted, confidential space for structured conversations around emotional wellbeing, stress, and resilience.', 'Some challenges are easier to navigate with the right support. Connect with appropriately qualified professionals for conversations around stress, emotional wellbeing and personal challenges.', 'Brain', '#15846e', 'Licensed Clinical Psychologists', '["Dealing with persistent stress, cognitive fatigue, or burnout", "Navigating a difficult personal or professional life transition", "Looking for structured emotional grounding and reflection tools"]'::jsonb, 'Individuals • High-Stress Roles', '["Licensed Clinical Psychologists (Ph.D. / Psy.D.)", "Certified Cognitive Behavioral Therapy (CBT) Practitioners", "Neuro-Resilience & Somatic Stress Regulation Specialists"]'::jsonb, '["Empathetic, confidential 1:1 exploratory consultations", "Evidence-based cognitive reframing and grounding protocols", "Actionable daily stress de-escalation routines"]'::jsonb, 'Advisory sessions provide structured guidance and reflective conversations. For medical emergencies or crisis care, please contact local emergency services immediately.', true, 3)
INSERT INTO public.mentors (id, headline, bio, experience_years, rating, review_count, verification_status, verified_categories, segment_id, primary_segment_id, credentials_url, credentials_verified_at, specialties, is_demo, created_at, updated_at) VALUES
('22222222-2222-2222-2222-222222222222', 'Licensed Clinical Psychologist & Executive Burnout Specialist', 'Dr. Evelyn Vasquez has spent 14 years bridging clinical psychology with high-stress executive performance. Having trained at Columbia University and served as a resident cognitive psychologist at Mount Sinai, she works directly with tech founders, partners, and high-growth executives navigating critical inflection points, acute decision fatigue, and systemic burnout.', 14, 4.98, 54, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/evelyn-vasquez-phd.pdf', '2025-01-15T10:00:00Z', ARRAY['Burnout Diagnostics', 'Decision Fatigue', 'CBT Protocols', 'Executive Stress'], true, '2024-11-01T08:00:00Z', '2025-02-01T12:00:00Z'),
('88888888-8888-8888-8888-888888888888', 'Consultant Clinical Neuropsychologist | Stress Resilience Researcher', 'Dr. Vikram Patel holds an M.Phil in Clinical Psychology and Cognitive Neuroscience from NIMHANS. He specializes in neuro-resilience, acute executive anxiety management, and cognitive performance under extreme workload.', 12, 4.97, 44, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/vikram-patel-nimhans.pdf', '2025-01-20T10:00:00Z', ARRAY['Neuropsychology', 'Executive Anxiety', 'Cognitive Stamina', 'Sleep Protocols'], true, '2024-11-15T08:00:00Z', '2025-02-08T10:00:00Z'),
('13131313-1313-1313-1313-131313131313', 'Licensed Clinical Psychologist & Panic / Acute Anxiety Specialist', 'Dr. Charlotte Weber has 16 years of clinical practice helping high-performing executives and creators resolve acute panic episodes, social performance anxiety, and catastrophic cognitive spirals.', 16, 4.99, 59, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/charlotte-weber.pdf', '2025-01-09T10:00:00Z', ARRAY['Panic De-escalation', 'Performance Anxiety', 'CBT Protocols', 'Exposure Protocols'], true, '2024-09-20T08:00:00Z', '2025-02-15T11:00:00Z'),
('14141414-1414-1414-1414-141414141414', 'Psychiatrist & Somatic Stress Regulation Specialist', 'Dr. Aravind Nair combines neurobiology with somatic stress regulation to help leaders recovering from chronic operational fatigue, nervous system overload, and sleep disruptions.', 15, 4.96, 47, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/aravind-nair.pdf', '2025-01-13T10:00:00Z', ARRAY['Somatic Regulation', 'Sleep Restructuring', 'Vagal Tone', 'Operational Fatigue'], true, '2024-10-14T08:00:00Z', '2025-02-14T12:00:00Z'),
('15151515-1515-1515-1515-151515151515', 'Cognitive Neuroscientist & Executive Focus Restoration Coach', 'Dr. Leila Kassir works with entrepreneurs, developers, and writers experiencing attentional fragmentation, digital dopamine exhaustion, and sustained focus decline.', 11, 4.93, 36, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/leila-kassir.pdf', '2025-01-21T10:00:00Z', ARRAY['Dopamine Reset', 'Attention Restoration', 'Deep Work Protocols', 'Digital Burnout'], true, '2024-11-04T08:00:00Z', '2025-02-12T11:00:00Z'),
('16161616-1616-1616-1616-161616161616', 'Clinical Psychologist & Executive Imposter Syndrome Specialist', 'Dr. Marcus Brooks provides empirical psychotherapy protocols to unpack deep-seated imposter phenomenon, perfectionistic paralysis, and emotional self-sabotage among high-visibility leaders.', 13, 4.95, 42, 'approved', ARRAY['mental-health'], '00000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000003', 'https://credentials.suggestkey.internal/marcus-brooks.pdf', '2025-01-18T10:00:00Z', ARRAY['Imposter Phenomenon', 'Perfectionistic Paralysis', 'Cognitive Restructuring', 'Self-Sabotage'], true, '2024-10-25T08:00:00Z', '2025-02-13T10:00:00Z')
INSERT INTO public.mentors (id, headline, bio, experience_years, rating, review_count, verification_status, verified_categories, segment_id, primary_segment_id, credentials_url, credentials_verified_at, specialties, is_demo, created_at, updated_at) VALUES
('66666666-6666-6666-6666-666666666666', 'Licensed Marriage & Family Therapist (LMFT) | Gottman Certified', 'Dr. Alistair Chen is a licensed LMFT with 15 years of clinical practice specializing in high-stress relationship dynamics, executive partnership calibration, and co-founder interpersonal alignment.', 15, 4.99, 62, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/alistair-chen-lmft.pdf', '2025-01-10T11:00:00Z', ARRAY['Gottman Method', 'Partnership Alignment', 'Family Systems', 'Conflict De-escalation'], true, '2024-10-12T08:00:00Z', '2025-02-01T12:00:00Z'),
('77777777-7777-7777-7777-777777777777', 'Certified Relationship Dynamics & Interpersonal Systems Specialist', 'Priya Sharma is a certified interpersonal relationship specialist and systemic mediator with 11 years of experience guiding high-performing professionals through intricate relationship transitions.', 11, 4.96, 38, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/priya-sharma-rel.pdf', '2025-01-18T14:00:00Z', ARRAY['Interpersonal Systems', 'Family Boundaries', 'Non-Violent Communication', 'Relational Resilience'], true, '2024-11-05T09:00:00Z', '2025-02-05T15:00:00Z'),
('99999999-9999-9999-9999-999999999999', 'Certified Gottman Method Practitioner & Interpersonal Conflict Mediator', 'Dr. Elena Rostova brings 13 years of clinical expertise focusing on high-conflict couple dynamics, emotional attunement, and trust rebuild protocols following major relational ruptures.', 13, 4.95, 29, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/elena-rostova.pdf', '2025-01-22T08:00:00Z', ARRAY['Trust Rebuild', 'Gottman Repair', 'High-Conflict Mediation', 'Emotional Attunement'], true, '2024-11-18T08:00:00Z', '2025-02-10T12:00:00Z'),
('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Intercultural Marriage & Pre-Commitment Dynamics Specialist', 'Rahul Mehta specializes in cross-cultural family alignment, extended family boundaries, and financial integration for modern couples planning long-term commitments.', 10, 4.92, 31, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/rahul-mehta.pdf', '2025-01-14T09:00:00Z', ARRAY['Intercultural Alignment', 'Financial Integration', 'Family Boundaries', 'Pre-Commitment'], true, '2024-10-28T10:00:00Z', '2025-02-12T14:00:00Z'),
('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'Attachment Styles & Intimacy Calibration Specialist', 'Dr. Sophia Vance helps high-achieving individuals understand anxious-avoidant attachment loops, navigate vulnerable communication, and create enduring emotional safety.', 14, 4.98, 51, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/sophia-vance.pdf', '2025-01-05T12:00:00Z', ARRAY['Attachment Theory', 'Vulnerable Communication', 'Anxious-Avoidant Loops', 'Intimacy'], true, '2024-09-15T08:00:00Z', '2025-02-14T10:00:00Z'),
('cccccccc-cccc-cccc-cccc-cccccccccccc', 'Systemic Family Mediator & Generational Communication Strategist', 'Maya Sen provides strategic mediation for multi-generational family businesses, complex estate disagreements, and parenting boundary conflicts.', 12, 4.91, 27, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/maya-sen.pdf', '2025-01-19T11:00:00Z', ARRAY['Generational Mediation', 'Family Business Dynamics', 'Co-Parenting', 'Boundary Enforcement'], true, '2024-11-10T12:00:00Z', '2025-02-11T16:00:00Z'),
('dddddddd-dddd-dddd-dddd-dddddddddddd', 'Conscious Separation & Collaborative Co-Parenting Consultant', 'David Kaufman guides high-net-worth parents and separating partners through low-friction co-parenting architecture and amicable transition planning.', 15, 4.94, 34, 'approved', ARRAY['relationship'], '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'https://credentials.suggestkey.internal/david-kaufman.pdf', '2025-01-08T10:00:00Z', ARRAY['Co-Parenting', 'Amicable Separation', 'Child-Centric Schedules', 'Relational Transitions'], true, '2024-10-01T09:00:00Z', '2025-02-09T10:00:00Z')
INSERT INTO public.mentors (id, headline, bio, experience_years, rating, review_count, verification_status, verified_categories, segment_id, primary_segment_id, credentials_url, credentials_verified_at, specialties, is_demo, created_at, updated_at) VALUES
('44444444-4444-4444-4444-444444444444', 'Principal Distributed Systems Architect | Ex-Google Staff Eng', 'Marcus Thorne has architected core distributed storage and stream processing infrastructure handling hundreds of billions of daily events. Over 16 years across Google, Uber, and high-frequency trading platforms.', 16, 5.0, 41, 'approved', ARRAY['career'], '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'https://credentials.suggestkey.internal/marcus-thorne-eng.pdf', '2025-01-10T14:00:00Z', ARRAY['Staff+ Trajectory', 'Executive Engineering Leadership', 'System Architecture', 'RFC Strategy'], true, '2024-10-15T09:00:00Z', '2025-02-05T15:00:00Z'),
('55555555-5555-5555-5555-555555555555', '2x Fintech Founder & Executive Negotiation Strategist | Ex-Venture Partner', 'Sarah Jenkins has built and exited two tech companies before serving as a venture partner evaluating executive leadership. She helps VP-level candidates master high-stakes compensation negotiations.', 12, 4.95, 36, 'approved', ARRAY['career'], '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'https://credentials.suggestkey.internal/sarah-jenkins-vc.pdf', '2025-01-08T09:30:00Z', ARRAY['Executive Compensation', 'C-Suite Pivots', 'Equity Negotiation', 'Board Placement'], true, '2024-09-10T12:00:00Z', '2025-02-10T16:00:00Z'),
('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee', 'VP Engineering & Tech Org Scaling Strategist | Ex-Uber, Meta', 'Arjun Kapoor has built and scaled engineering teams from 20 to 300+ engineers across hyper-growth tech orgs. He advises Directors, Heads of Eng, and VP candidates on technical organizational design.', 15, 4.96, 48, 'approved', ARRAY['career'], '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'https://credentials.suggestkey.internal/arjun-kapoor.pdf', '2025-01-11T10:00:00Z', ARRAY['VP of Eng Transition', 'Org Structure', 'Executive Stakeholder Alignment', 'Retention Strategy'], true, '2024-10-18T10:00:00Z', '2025-02-14T11:00:00Z'),
('ffffffff-ffff-ffff-ffff-ffffffffffff', 'Group Product Manager & Head of Product Leadership Coach', 'Rachel Zhao has led product organizations across Stripe, Airbnb, and B2B SaaS unicorns. She advises Senior Product Managers, Group PMs, and Product Directors on product strategy.', 13, 4.97, 52, 'approved', ARRAY['career'], '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'https://credentials.suggestkey.internal/rachel-zhao.pdf', '2025-01-16T12:00:00Z', ARRAY['Product Strategy', 'GPM to Director', 'Metrics Defensibility', 'Board Pitching'], true, '2024-10-05T08:00:00Z', '2025-02-12T15:00:00Z'),
('10101010-1010-1010-1010-101010101010', 'Tech Founder Coach & Seed-to-Series B Operator', 'Vikram Singh has co-founded 2 VC-backed startups and advised 30+ founders on CEO executive presence, early compensation structures, and founder-to-executive transitions.', 11, 4.93, 28, 'approved', ARRAY['career'], '00000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'https://credentials.suggestkey.internal/vikram-singh.pdf', '2025-01-12T14:00:00Z', ARRAY['Founder Leadership', 'Early-Stage Scaling', 'Cap Table Management', 'CEO Presence'], true, '2024-11-02T10:00:00Z', '2025-02-13T12:00:00Z'),
('12121212-1212-1212-1212-121212121212', 'Chief of Staff & Strategic Operations Mentor', 'Elena Moreno mentors Chiefs of Staff, VP of Operations, and general managers across high-velocity technology firms on managing C-suite priorities and cross-functional execution.', 10, 4.